std::vector<std::vector<float>> walk_angle_float = parseCsvFromString(csv_data);

# define PI 3.14159265359
int angle_to_position(float angle) {
  // return 7500 + 4000 * angle / 135;
  return 7500 + 4000 * (angle * 180 / PI) / 135;
}

void servo_task(void *parameter) {
  while(true) {
    if (!walking) {
      vTaskDelay(100);
      continue;
    }
    // 角度指令
    for (size_t i = 0; i < ids.size(); ++i) {
      krs->setServoPosition(rcb4_index[i], angle_to_position(walk_angle_float[walk_angle_index][i]));
    }
    vTaskDelay(40);
    walk_angle_index++;
    if (walk_angle_index >= NUM_SEQUENCE) {
      walk_angle_index = 0;
    }
  }
}

void servo_on(bool on) {
  if (servo_on_state) {
    if (!on) {
      walking = false;
      for (size_t i = 0; i < ids.size(); ++i) {
        krs->setServoFree(ids[i]);
      }
    }
  } else {
    if (on) {
      for (size_t i = 0; i < ids.size(); ++i) {
        krs->setServoHold(ids[i]);
      }
    }
  }
  servo_on_state = on;
}

void display() {
  DEBUG_SERIAL.clear();
  DEBUG_SERIAL.setCursor(0,0);
  for (size_t i = 0; i < ids.size(); ++i) {
    DEBUG_SERIAL.printf("%d,", ids[i]);
  }

  DEBUG_SERIAL.setCursor(0,30);
  if (servo_on_state) {
    DEBUG_SERIAL.println("servo on");
  } else {
    DEBUG_SERIAL.println("servo free");
  }

  DEBUG_SERIAL.setCursor(0,40);
  if(walking){
    DEBUG_SERIAL.println("walking start");
    for (size_t i = 0; i < ids.size(); ++i) {
      DEBUG_SERIAL.printf("%d: %d\n", rcb4_index[i], angle_to_position(walk_angle_float[walk_angle_index][ids[i]]));
    }
  }else{
    DEBUG_SERIAL.println("walking stop");
  }
}

void setup() {
    DEBUG_SERIAL.begin();
    DEBUG_SERIAL.println("start");
    // Wait for board to stabilize
    delay(2000);

    const long BAUDRATE = 1250000;
    Serial1.begin(BAUDRATE, SERIAL_8E1, RX_PIN, TX_PIN, false, TIMEOUT);
    krs = new IcsHardSerialClass(&Serial1, BAUDRATE, TIMEOUT, EN_PIN);
    krs->begin();
    while (ids.size() < NUM_SERVO) {
        ids.clear();
        stats_vector.clear();

        uint32_t idBits = krs->scanIDs();
        for (int servo_id = 0; servo_id < NUM_SERVO; ++servo_id) {
            if (static_cast<int>(idBits) & (1 << servo_id)) {
                ids.push_back(servo_id);
                RunningStats stats;
                stats_vector.push_back(stats);
            }
        }
        for (size_t i = 0; i < ids.size(); ++i) {
          DEBUG_SERIAL.printf("%d,", ids[i]);
        }
    }
    for (size_t i = 0; i < ids.size(); ++i) {
      while (krs->setSpeed(ids[i], 80) == -1) {
        delay(10);
      }
      while (krs->setStretch(ids[i], 30) == -1) {
        delay(10);
      }
      DEBUG_SERIAL.printf("%d ", ids[i]);
    }
    button_manager.createTask(1);
    xTaskCreatePinnedToCore(servo_task, "Servo Task", 2048, NULL, 24, NULL, 0);
}

void loop() {
  switch (button_manager.getButtonState()) {
  case 0:
    button_updated = false;
    break;
  case 1:
    if (!button_updated) {
      if (servo_on_state) {
        servo_on(false);
      }else {
        servo_on(true);
      }
      button_updated = true;
    }
    break;
  case 2:
    if (!button_updated) {
      if (!walking) {
        servo_on(true);
        // 初期姿勢になる
        walk_angle_index = 0;
      }
      walking = !walking;
      button_updated = true;
    }
    break;
  }
  display();
  delay(200);
}
